// Toggle user-only message filter
let userOnlyMode = false;

function toggleUserOnly() {
    userOnlyMode = !userOnlyMode;
    const toggle = document.getElementById('userOnlyToggle');
    const container = document.getElementById('messagesContainer');

    if (userOnlyMode) {
        toggle.classList.add('active');
        container.classList.add('user-only');
        // Collapse all expansions when entering user-only mode
        collapseAllUserMessages();
    } else {
        toggle.classList.remove('active');
        container.classList.remove('user-only');
        // Clean up expanded classes
        collapseAllUserMessages();
    }
}

function collapseAllUserMessages() {
    document.querySelectorAll('.message.user.expanded').forEach(el => el.classList.remove('expanded'));
    document.querySelectorAll('.message.expanded-child').forEach(el => el.classList.remove('expanded-child'));
}

function toggleUserMessageExpansion(userMsgEl) {
    if (!userOnlyMode) return;

    const wasExpanded = userMsgEl.classList.contains('expanded');

    // Collapse all first
    collapseAllUserMessages();

    if (wasExpanded) {
        // Just collapse, don't re-expand
        return;
    }

    // Expand this user message and show all following messages until next user message
    userMsgEl.classList.add('expanded');

    let nextEl = userMsgEl.nextElementSibling;
    while (nextEl && !nextEl.classList.contains('user')) {
        nextEl.classList.add('expanded-child');
        nextEl = nextEl.nextElementSibling;
    }
}

